/*
 * nano_j2me - nj_font.c
 *
 * The bitmap font registry declared in nj_gfx.h.
 *
 * Design notes
 * ------------
 *  - The glyph tables in nj_font_data.h are generated by tools/gen_fonts.py
 *    and live in .rodata.  nj_font_builtin() hands out pointers to immutable
 *    nj_font descriptors built from them; nothing here is ever written.
 *  - The runtime keeps no mutable global font state.  A caller that wants a
 *    per-instance fallback (the CJK hook, say) owns an nj_fontset: it holds
 *    mutable *copies* of the builtins, one per (size, plain/bold) pair, so
 *    nj_fontset_set_fallback() can install a pointer without touching data
 *    shared with any other nj_vm.
 *  - ITALIC and UNDERLINED have no bitmaps of their own: they reuse the PLAIN
 *    (or BOLD) glyphs and are recorded in nj_font.style for the rasteriser.
 *    That is why s_builtin carries eight entries per size even though there
 *    are only two bitmaps per size.
 *  - The fontset has six slots - three sizes times plain/bold - exactly as
 *    nj_gfx.h documents, so a request for an italic font from a set resolves
 *    to the plain (or bold) instance of that size.  Ask nj_font_builtin()
 *    directly when the style bits themselves matter.
 */

#include "nj2me/nj_gfx.h"

#include "nj_font_data.h"

/* ------------------------------------------------------------------ */
/* Layout constants                                                    */
/* ------------------------------------------------------------------ */

#define NJ_FONT_SIZE_COUNT 3
#define NJ_FONT_STYLE_COUNT 8   /* bold | italic | underlined combinations */
#define NJ_FONT_SLOT_STYLES 2   /* per fontset slot: plain and bold only   */
#define NJ_FONT_FALLBACK_MAX_DEPTH 8

#define NJ_FONT_STYLE_MASK \
    (NJ_FONT_STYLE_BOLD | NJ_FONT_STYLE_ITALIC | NJ_FONT_STYLE_UNDERLINED)

/*
 * One immutable descriptor.  `bmp` points at one of the generated tables,
 * whose geometry is (last_char - first_char + 1) cells of glyph_h rows of
 * (glyph_w + 7) / 8 bytes - see nj_gfx.h.
 */
#define NJ_FONT_ENTRY(nm, szv, styv, wv, hv, av, dv, lv, bmp)  \
    {                                                          \
        (nm), (hv), (av), (dv), (lv), (styv), (szv), 0,        \
        (nj_u2)NJ_FONT_DATA_FIRST, (nj_u2)NJ_FONT_DATA_LAST,   \
        (wv), (hv), (bmp),                                     \
        NULL, NULL, NULL, NULL                                 \
    }

